import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"家人","description":"东坡易传 - 家人","frontmatter":{"title":"家人","description":"东坡易传 - 家人"},"headers":[],"relativePath":"zh/classics/dongpo/038.md","filePath":"zh/classics/dongpo/038.md"}'),o={name:"zh/classics/dongpo/038.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="家人" tabindex="-1">家人 <a class="header-anchor" href="#家人" aria-label="Permalink to “家人”">​</a></h1><p>“家人”：利女貞。</p><p>《彖》曰：“家人”，女正位乎內【謂二也】。男正位乎外【謂五也。】。男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父、子子、兄兄、弟弟、夫夫、婦婦而家道正，正家而天下定矣。</p><p>象曰：風自火出，“家人”。君子以言有物而行有恆。</p><p>火之所以盛者，風也；火盛而風出焉。家之所以正者，我也；家正而我與焉。</p><p>初九：閒有家，悔亡。象曰：“閒有家”，志未變也。</p><p>家人之道，寬則傷義，猛則傷恩。然則是無適而可乎？曰：“君子以言有物而行有恆。”至矣，言之有物也，行之有恆也！雖有悍婦、暴子弟，莫敢不肅然，而未嘗廢恩也，此所以爲至也。曾子曰：“君子所貴乎道者三：動容貌，斯遠曝慢矣；正顏色，斯近信矣；出辭氣，斯遠鄙倍矣。”如是，何閒之有？初九用剛於家之始，九三用剛於家之成，是以皆有悔也。夫所以至於“閒”者？惟德不足故也。德既不足，而又忘閒焉，則志變矣。及其未變而閒之，故“悔亡”。</p><p>六二：無攸遂，在中饋，貞吉。象曰：六二之“吉”，順以“巽”也。</p><p>有中饋，無遂事，婦人之正也。</p><p>九三：家人嗃嗃，悔厲，吉。婦子嘻嘻，終吝。象曰：“家人嗃嗃”，未失也。“婦子嘻嘻”，失家節也。</p><p>以陽居陽，過於用剛，故悔且危也。人見其悔且危也，而矯之以寬，則家敗矣。故告之以斯人之終吉，戒之以失節之終吝。</p><p>六四：富家，大吉。象曰：“富家大吉”，順在位也。</p><p>“家人”有四陽二陰，而陰皆不失其位，以聽於陽。陽爲政而陰聽之，家欲不治不可得也。富者治之極也，故六二“貞吉”，其治也；六四“富家”，其極也。以治極致富，則其富可久，此之謂“大吉”。</p><p>九五：王假有家，勿恤，吉。象曰：“王假有家”，交相愛也。</p><p>“假”，至也。王至有家，則是家也大矣。王者以天下爲一家，“家人”之家近而相瀆，天下之家遠而相忘，知其患在於相瀆也，故推嚴別遠以存相忘之意，知其患在於相忘也。故簡易“勿恤”，以通相愛之情。“家人”四陽，惟九五有人君之德，故稱其德、論天下之家焉。君臣欲其如父子，父子欲其如君臣，聖人之意也。</p><p>上九：有孚，威如，終吉。象曰：“威如”之“吉”，反身之謂也。</p><p>上九之所信者，三也。家人之無應者，惟三與上而已。人皆剛柔相與，而己獨兩剛相臨①，是以終身不忘畏也。畏威如疾，民之上也，故畏人者人亦畏之，慢人者人亦慢之，此之謂“反身”。凡言終者，其始未必然也，“婦子嘻嘻”，其始可樂；“威如之吉”其始苦之。</p><p>【校注】 ① 而己獨兩剛相臨：《蘇氏易傳》作“而已獨兩剛相臨”，誤。</p>',18)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
